import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"FaultDeck MVP 计划(P0)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/design/mvp-plan.md","filePath":"zh/design/mvp-plan.md"}`),a={name:`zh/design/mvp-plan.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="faultdeck-mvp-计划-p0" tabindex="-1">FaultDeck MVP 计划(P0) <a class="header-anchor" href="#faultdeck-mvp-计划-p0" aria-label="Permalink to “FaultDeck MVP 计划(P0)”">​</a></h1><p>日期:2026-11-02 · 源:ChatGPT 架构评审(存档见 docs/review/)+ 用户拍板</p><h2 id="p0-范围-最小可用-tcp-故障实验" tabindex="-1">P0 范围:最小可用 TCP 故障实验 <a class="header-anchor" href="#p0-范围-最小可用-tcp-故障实验" aria-label="Permalink to “P0 范围:最小可用 TCP 故障实验”">​</a></h2><ul><li>Rust CLI(<code>faultdeck</code>)</li><li>Toxiproxy Adapter(TCP 代理故障注入)</li><li>实验 YAML DSL(场景编排:步骤/持续时间/目标)</li><li>故障类型:延迟(latency)/断线(cut connection)/黑洞(timeout)/带宽限制(bandwidth)</li><li>自动恢复(Lifecycle+Rollback,Safety Guard 看门狗:实验中断/进程被杀也必须撤销)</li><li>JSON 实验报告(时间线、注入参数、恢复验证结果)</li></ul><h2 id="硬性验收" tabindex="-1">硬性验收 <a class="header-anchor" href="#硬性验收" aria-label="Permalink to “硬性验收”">​</a></h2><ol><li><code>faultdeck run examples/tcp-reconnect.yaml</code> 全自动跑通,不依赖 GUI</li><li><strong>Ctrl-C / kill -9 后故障 100% 被撤销</strong>(watchdog 兜底),目标连接恢复正常</li><li>报告 JSON 可复现:同 YAML 重跑结果一致</li><li>Safety Guard 拒绝对管理网段(SSH/ZeroTier 所在网卡/网段)的实验</li></ol><h2 id="crate-划分" tabindex="-1">Crate 划分 <a class="header-anchor" href="#crate-划分" aria-label="Permalink to “Crate 划分”">​</a></h2><table tabindex="0"><thead><tr><th>crate</th><th>职责</th></tr></thead><tbody><tr><td>faultdeck-core</td><td>故障类型、目标、状态模型</td></tr><tr><td>faultdeck-scenario</td><td>实验 YAML DSL 解析与调度</td></tr><tr><td>faultdeck-backend</td><td>Backend Trait(语义声明+能力查询)</td></tr><tr><td>faultdeck-toxiproxy</td><td>Toxiproxy REST API 适配</td></tr><tr><td>faultdeck-safety</td><td>Watchdog、Lease、Rollback</td></tr><tr><td>faultdeck-report</td><td>指标采集与 JSON 报告</td></tr><tr><td>faultdeck-cli</td><td>命令行入口</td></tr></tbody></table><h2 id="里程碑拆分" tabindex="-1">里程碑拆分 <a class="header-anchor" href="#里程碑拆分" aria-label="Permalink to “里程碑拆分”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> FD-P0-1 仓库骨架:cargo workspace + 7 crate + CI(rustfmt/clippy/test)</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> FD-P0-2 core 类型模型 + scenario YAML 解析(serde,含校验报错)</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> FD-P0-3 toxiproxy adapter(启动/托管 toxiproxy-server,代理与故障 CRUD)</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> FD-P0-4 safety:watchdog 进程 + lease + 强制回滚(含 fork 后父死子活场景)</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> FD-P0-5 CLI run/report 子命令 + JSON 报告</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> FD-P0-6 examples 三个场景 + integration/recovery 测试 + README 快速上手</label></li></ul><h2 id="p1-预告" tabindex="-1">P1 预告 <a class="header-anchor" href="#p1-预告" aria-label="Permalink to “P1 预告”">​</a></h2><p>tc/netem Adapter(netlink 直操而非 shell 调 tc)、TCP/UDP、流量选择(flow 分流)、突发丢包、乱序、netns 隔离;测试环境用独立 netns,避免污染宿主。</p><h2 id="跨机控制-2026-11-02-补充-windows-控制端-→-linux-被测端" tabindex="-1">跨机控制(2026-11-02 补充:Windows 控制端 → Linux 被测端) <a class="header-anchor" href="#跨机控制-2026-11-02-补充-windows-控制端-→-linux-被测端" aria-label="Permalink to “跨机控制(2026-11-02 补充:Windows 控制端 → Linux 被测端)”">​</a></h2><ul><li>P0 即可达成:Windows 跑 faultdeck CLI,Linux 被测端跑 toxiproxy-server,经 Toxiproxy REST API 注入延迟/断连/黑洞/限带宽(控制端与被测端仅需网络可达——不需要 SSH、不需要 root、不动网卡)。</li><li>P1 升级:tc/netem 级故障(真丢包/抖动/隔离)——推荐在 Linux 被测端常驻 faultdeck-agent(监听本地端口接收控制端指令,本机执行 netem/iptables,带安全守卫:管理网段白名单,绝不掐管理流量);SSH 代执行作备选。原 P3 的「远程 Agent」形态提前到 P1。</li></ul><h2 id="连接方向与报告-2026-11-02-补充" tabindex="-1">连接方向与报告(2026-11-02 补充) <a class="header-anchor" href="#连接方向与报告-2026-11-02-补充" aria-label="Permalink to “连接方向与报告(2026-11-02 补充)”">​</a></h2><ul><li><p>Agent 双模式:Mode A=agent 监听(目标公网可达);Mode B=控制端监听(目标在 NAT 后,agent 主动出站反向拨号,长连隧道断线自动重连)。单条 TCP 长连接承载指令/事件/日志/报告——两模式协议对称。</p></li><li><p>报告是核心功能:唯一事实源(YAML+hash、注入时间线、恢复证据、断言结果、一键重现),JSON + HTML 双格式,历史对比做回归验证。</p></li><li><p>Coordinator 协调者模式(多目标推荐形态):部署在 agent 与控制端都可达处;agent 注册(身份/能力/心跳),控制端附着发起实验;协调者路由指令、存档报告,解决双向 NAT 并提供多目标舰队视图;与直连模式 A/B 递进(单目标直连,多目标走协调者);舰队场景可运行于 meshlet 虚拟网之上。</p></li></ul>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};